const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Polygon([[
        [-89.70, 29.40],
        [-89.70, 29.30],
        [-89.60, 29.30],
        [-89.60, 29.40],
        [-89.70, 29.40]
    ]], null, false);

    const startPeriod = {
        label: '1985',
        start: '1985-01-01',
        end: '1985-12-31'
    };
    const endPeriod = {
        label: '2024',
        start: '2023-01-01',
        end: '2024-06-01'
    };

    // 2. Data Acquisition & Processing Logic
    function getCloudMask(image) {
        const qa = image.select('QA_PIXEL');
        const dilatedCloud = (1 << 1);
        const cirrus = (1 << 2);
        const cloud = (1 << 3);
        const cloudShadow = (1 << 4);
        const mask = qa.bitwiseAnd(dilatedCloud).eq(0)
            .and(qa.bitwiseAnd(cirrus).eq(0))
            .and(qa.bitwiseAnd(cloud).eq(0))
            .and(qa.bitwiseAnd(cloudShadow).eq(0));
        return image.updateMask(mask);
    }

    function calculateMNDWI(image) {
        // Landsat 5, 7 use bands B2 (Green) and B5 (SWIR1)
        // Landsat 8, 9 use bands B3 (Green) and B6 (SWIR1)
        const green = image.select(['SR_B2', 'SR_B3'], ['Green']).toFloat();
        const swir1 = image.select(['SR_B5', 'SR_B6'], ['SWIR1']).toFloat();
        return green.subtract(swir1).divide(green.add(swir1)).rename('MNDWI');
    }

    function getComposite(period) {
        let l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').filterBounds(geometry).filterDate(period.start, period.end);
        let l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(geometry).filterDate(period.start, period.end);
        let l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(geometry).filterDate(period.start, period.end);

        const mergedCollection = ee.ImageCollection(l5.merge(l8).merge(l9));

        if (mergedCollection.size().getInfo() === 0) {
            return { image: null, count: 0 };
        }

        const composite = mergedCollection
            .map(getCloudMask)
            .map(calculateMNDWI)
            .median(); // Median composite to fill gaps and reduce noise

        return { image: composite, count: mergedCollection.size().getInfo() };
    }

    // 3. Image Creation and Validation
    const composite1985_obj = getComposite(startPeriod);
    const composite2024_obj = getComposite(endPeriod);

    console.log(`Image count 1985: ${composite1985_obj.count}`);
    console.log(`Image count 2024: ${composite2024_obj.count}`);

    if (!composite1985_obj.image || !composite2024_obj.image) {
        console.log("Empty collection for one or both periods.");
        console.log("A"); // C1 is not the answer tag
        return;
    }

    const image1985 = composite1985_obj.image;
    const image2024 = composite2024_obj.image;

    // Define thresholds for water and non-water (wetland)
    const waterThreshold = 0;
    const water1985 = image1985.select('MNDWI').gt(waterThreshold);
    const water2024 = image2024.select('MNDWI').gt(waterThreshold);
    const nonWater1985 = image1985.select('MNDWI').lte(waterThreshold);
    const nonWater2024 = image2024.select('MNDWI').lte(waterThreshold);

    const scale = 300; // Use a larger scale to avoid timeout
    const commonArgs = {
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    };

    // 4. Calculation
    try {
        const waterPixels1985 = water1985.multiply(ee.Image.pixelArea()).reduceRegion({reducer: ee.Reducer.sum(), ...commonArgs}).get('MNDWI').getInfo();
        const nonWaterPixels1985 = nonWater1985.multiply(ee.Image.pixelArea()).reduceRegion({reducer: ee.Reducer.sum(), ...commonArgs}).get('MNDWI').getInfo();

        const waterPixels2024 = water2024.multiply(ee.Image.pixelArea()).reduceRegion({reducer: ee.Reducer.sum(), ...commonArgs}).get('MNDWI').getInfo();
        const nonWaterPixels2024 = nonWater2024.multiply(ee.Image.pixelArea()).reduceRegion({reducer: ee.Reducer.sum(), ...commonArgs}).get('MNDWI').getInfo();

        if (waterPixels1985 === null || nonWaterPixels1985 === null || waterPixels2024 === null || nonWaterPixels2024 === null) {
             console.log("Calculation resulted in null values, likely no valid pixels.");
             console.log("C2");
             return;
        }

        // Avoid division by zero
        if (nonWaterPixels1985 === 0 || nonWaterPixels2024 === 0) {
            console.log("No non-water (wetland) pixels found in one period.");
            console.log("C2");
            return;
        }

        const ratio1985 = waterPixels1985 / nonWaterPixels1985;
        const ratio2024 = waterPixels2024 / nonWaterPixels2024;

        // 5. Validation & Final Answer
        console.log(`1985 Water Area (m^2): ${waterPixels1985.toExponential(2)}`);
        console.log(`1985 Wetland Area (m^2): ${nonWaterPixels1985.toExponential(2)}`);
        console.log(`1985 Water/Wetland Ratio: ${ratio1985.toFixed(3)}`);

        console.log(`2024 Water Area (m^2): ${waterPixels2024.toExponential(2)}`);
        console.log(`2024 Wetland Area (m^2): ${nonWaterPixels2024.toExponential(2)}`);
        console.log(`2024 Water/Wetland Ratio: ${ratio2024.toFixed(3)}`);

        if (ratio2024 > ratio1985) {
            console.log("The ratio of open water to wetland area increased.");
            console.log("A");
        } else {
            console.log("The ratio of open water to wetland area did not increase.");
            console.log("B");
        }

    } catch (e) {
        console.error("An error occurred during GEE processing:", e);
        console.log("D");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error("Initialization failed:", e);
    console.log("D");
});
